
import pandas as pd

# Load the summary generated by churn_analysis.py
df = pd.read_csv("churn_summary.csv")

print("CUSTOMER CHURN ANALYSIS")
print("=" * 40)

print("\nChurn rates by segment:")
print(df.to_string(index=False))

# Identify the segments with the highest churn
segments = df[df["segment"] != "Overall"]

top_segments = segments.sort_values(
    by="churn_rate_pct",
    ascending=False
).head(5)

print("\nTOP 5 HIGH-CHURN SEGMENTS")
print(top_segments.to_string(index=False))

# Save the results
top_segments.to_csv(
    "top_churn_segments.csv",
    index=False
)

print("\nAnalysis completed!")
print("Saved: top_churn_segments.csv")
